  {
    "alert_id": "DTG_WEIGHT_GAIN_METABOLIC",
    "title": "DTG-associated weight gain and metabolic decompensation",
    "message": "Guidelines state weight gain should be discussed when starting all ART regimens, with proactive diet and exercise advice, as obesity is an increasing problem particularly among women. Since switching to DTG 18 months ago, this patient gained 17 kg (65 to 82 kg), BMI rose from 25.6 to 32.4, and waist circumference is 96 cm. Acanthosis nigricans indicates insulin resistance. Fasting glucose worsened from 92 to 118 mg/dL (impaired), HbA1c 6.1% is pre-diabetic. Lipid profile is atherogenic: LDL 148, HDL 38, triglycerides 212. BP rose from 118/74 to 138/88. DTG is strongly associated with weight gain; EFV (prior regimen) may have had a weight-suppressive effect, making the gain more pronounced after switch. Family history of Type 2 Diabetes compounds risk. Non-drug contributors (diet, physical activity) should also be assessed.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Provide structured diet and exercise counselling. Consider switching DTG to an alternative agent. Refer for diabetes prevention programme and repeat fasting glucose and HbA1c in 3 months.",
    "citations": [
      {"page_number": 8, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p8_c4"}
    ]
  },
  {
    "alert_id": "DTG_GLUCOSE_MONITORING_GAP",
    "title": "Missing glucose monitoring after DTG initiation",
    "message": "Uganda guidelines specify glucose monitoring every 3 months for the first year when transitioning to DTG. This patient transitioned to DTG 18 months ago, yet today's fasting glucose (118 mg/dL) and HbA1c (6.1%) appear to be the first glycemic assessments since the switch. Baseline fasting glucose was 92 mg/dL at the time of transition. The development of pre-diabetes may have been detected earlier had quarterly monitoring been performed as recommended.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Although the first-year quarterly window has passed, establish ongoing glucose monitoring every 3-6 months given current pre-diabetic status and high metabolic risk.",
    "citations": [
      {"page_number": 5, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p5_c3"}
    ]
  },
  {
    "alert_id": "MISSING_CLINICIAN_PLAN",
    "title": "No assessment or plan documented for abnormal findings",
    "message": "The clinician has not documented any assessment or plan for this visit despite multiple clinically significant findings: 17 kg weight gain since ART switch, new pre-diabetes (HbA1c 6.1%, fasting glucose 118 mg/dL), dyslipidemia (LDL 148, triglycerides 212, HDL 38), elevated BP (138/88), acanthosis nigricans, and BMI 32.4. Guidelines recommend proactive weight management advice for all patients on ART. The absence of a plan risks missed intervention for a patient at high cardiometabolic risk.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document a comprehensive plan addressing weight management, glucose monitoring, lipid assessment, BP follow-up, and consideration of ART modification.",
    "citations": [
      {"page_number": 8, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p8_c4"}
    ]
  }
]
